def resolve_search_window_or_bounds(
    current_timestamp: float,
    phrase: str,
    target_domain: str,
    timestamp_intent: str,
    direction: str,
    content_keyword: str = "",
    lookback_days: int = 0,
    timezone_offset: float = 0.0,
) -> dict:
    min_timestamp = 315529200.0
    now = float(current_timestamp)
    if now <= 0:
        return {
            "target_tool_name": "",
            "search_kwargs": {},
            "should_call_search": False,
            "abstain_reason": "missing_current_timestamp",
            "interpretation": "",
            "bounds_source": "abstain",
        }
    domain = str(target_domain or "").strip().lower()
    if domain == "message":
        tool_name = "search_messages"
    elif domain == "reminder":
        tool_name = "search_reminder"
    else:
        return {
            "target_tool_name": "",
            "search_kwargs": {},
            "should_call_search": False,
            "abstain_reason": "unsupported_target_domain",
            "interpretation": "",
            "bounds_source": "abstain",
        }
    intent = str(timestamp_intent or "").strip().lower()
    if domain == "message":
        lower_key = "creation_timestamp_lowerbound"
        upper_key = "creation_timestamp_upperbound"
    elif intent == "creation":
        lower_key = "creation_timestamp_lowerbound"
        upper_key = "creation_timestamp_upperbound"
    elif intent == "reminder":
        lower_key = "reminder_timestamp_lowerbound"
        upper_key = "reminder_timestamp_upperbound"
    else:
        return {
            "target_tool_name": "",
            "search_kwargs": {},
            "should_call_search": False,
            "abstain_reason": "unsupported_timestamp_intent",
            "interpretation": "",
            "bounds_source": "abstain",
        }
    normalized_direction = str(direction or "").strip().lower()
    normalized_phrase = str(phrase or "").strip().lower()
    if not normalized_direction:
        if normalized_phrase in ("yesterday", "today", "later today", "later_today", "upcoming", "recent", "latest", "oldest"):
            normalized_direction = normalized_phrase.replace(" ", "_")
        else:
            return {
                "target_tool_name": "",
                "search_kwargs": {},
                "should_call_search": False,
                "abstain_reason": "ambiguous_phrase",
                "interpretation": "",
                "bounds_source": "abstain",
            }
    offset_seconds = float(timezone_offset) * 3600.0
    local_now = now + offset_seconds
    local_day_start = float(int(local_now // 86400.0) * 86400.0)
    day_start = local_day_start - offset_seconds
    next_day_start = day_start + 86400.0
    kwargs = {}
    interpretation = normalized_direction
    bounds_source = "resolved_direction"
    if normalized_direction == "yesterday":
        kwargs[lower_key] = max(min_timestamp, day_start - 86400.0)
        kwargs[upper_key] = max(min_timestamp, day_start - 1.0)
    elif normalized_direction == "today":
        kwargs[lower_key] = max(min_timestamp, day_start)
        kwargs[upper_key] = max(min_timestamp, next_day_start - 1.0)
    elif normalized_direction == "later_today":
        kwargs[lower_key] = max(min_timestamp, now)
        kwargs[upper_key] = max(min_timestamp, next_day_start - 1.0)
    elif normalized_direction == "upcoming":
        kwargs[lower_key] = max(min_timestamp, now)
    elif normalized_direction == "recent":
        days = int(lookback_days)
        if days <= 0:
            days = 7
        kwargs[lower_key] = max(min_timestamp, now - days * 86400.0)
        kwargs[upper_key] = max(min_timestamp, now)
    elif normalized_direction in ("latest", "oldest"):
        if domain == "message":
            kwargs[upper_key] = max(min_timestamp, now)
        else:
            days = int(lookback_days)
            if days <= 0:
                days = 3650
            kwargs[lower_key] = max(min_timestamp, now - days * 86400.0)
            kwargs[upper_key] = max(min_timestamp, now)
    elif normalized_direction == "custom":
        days = int(lookback_days)
        if days <= 0:
            return {
                "target_tool_name": "",
                "search_kwargs": {},
                "should_call_search": False,
                "abstain_reason": "custom_window_requires_positive_lookback_days",
                "interpretation": "",
                "bounds_source": "abstain",
            }
        kwargs[lower_key] = max(min_timestamp, now - days * 86400.0)
        kwargs[upper_key] = max(min_timestamp, now)
        interpretation = "custom_lookback"
    else:
        return {
            "target_tool_name": "",
            "search_kwargs": {},
            "should_call_search": False,
            "abstain_reason": "unsupported_direction",
            "interpretation": "",
            "bounds_source": "abstain",
        }
    if str(content_keyword or "").strip():
        kwargs["content"] = str(content_keyword)
    if not kwargs:
        return {
            "target_tool_name": "",
            "search_kwargs": {},
            "should_call_search": False,
            "abstain_reason": "no_search_criteria_prepared",
            "interpretation": "",
            "bounds_source": "abstain",
        }
    return {
        "target_tool_name": tool_name,
        "search_kwargs": kwargs,
        "should_call_search": True,
        "abstain_reason": "",
        "interpretation": interpretation,
        "bounds_source": bounds_source,
    }

def select_recency_target_and_prepare_action(records: list, timestamp_key: str, selection_mode: str, action_type: str, constraints: dict = None, updates: dict = None) -> dict:
    """Select a unique recency target and optionally prepare preserved side-effect kwargs."""
    constraints = constraints if isinstance(constraints, dict) else {}
    updates = updates if isinstance(updates, dict) else {}
    raw_action = (action_type or "").strip().lower() if isinstance(action_type, str) else ""

    def empty(reason, selected_timestamp=0.0, tie_candidates=None, safety_notes="abstain; no safe unique action"):
        return {
            "selected_record": {},
            "selected_index": -1,
            "selected_id": "",
            "selected_timestamp": float(selected_timestamp or 0.0),
            "value": "",
            "downstream_tool_name": "",
            "downstream_tool_kwargs": {},
            "should_call_tool": False,
            "tie_candidates": tie_candidates if isinstance(tie_candidates, list) else [],
            "abstain_reason": str(reason or ""),
            "safety_notes": safety_notes,
            "final_answer_recommendation": "abstain:" + str(reason or "insufficient_information"),
        }

    def selected_only(reason, selected_index, selected_record, selected_timestamp, downstream_tool_name=""):
        selected_id = _select_id(selected_record)
        return {
            "selected_record": selected_record,
            "selected_index": int(selected_index),
            "selected_id": selected_id,
            "selected_timestamp": float(selected_timestamp),
            "value": selected_id,
            "downstream_tool_name": str(downstream_tool_name or ""),
            "downstream_tool_kwargs": {},
            "should_call_tool": False,
            "tie_candidates": [],
            "abstain_reason": str(reason or ""),
            "safety_notes": "selected target only; collect or compute update fields before side-effect",
            "final_answer_recommendation": "use_selected_record:" + str(reason or "selection_only"),
        }

    if not isinstance(records, list) or len(records) == 0:
        return empty("no_records")
    mode = (selection_mode or "").strip().lower() if isinstance(selection_mode, str) else ""
    if mode not in ("latest", "oldest"):
        return empty("invalid_selection_mode")

    def norm(field, value):
        if value is None:
            return ""
        text = str(value)
        fname = str(field).lower()
        if "phone" in fname or "number" in fname:
            return "".join(ch for ch in text if ch.isdigit())
        return text.strip().lower()

    def _select_id(record):
        if not isinstance(record, dict):
            return ""
        for key in ("person_id", "sender_person_id", "recipient_person_id", "reminder_id", "message_id", "id"):
            value = record.get(key)
            if value not in (None, ""):
                return str(value)
        return ""

    filtered = []
    for idx, record in enumerate(records):
        if not isinstance(record, dict):
            continue
        ok = True
        for field, expected in constraints.items():
            if field not in record or norm(field, record.get(field)) != norm(field, expected):
                ok = False
                break
        if ok:
            filtered.append((idx, record))
    if not filtered:
        return empty("no_matching_constraints")

    candidates = []
    for idx, record in filtered:
        raw_ts = record.get(timestamp_key)
        if isinstance(raw_ts, bool) or not isinstance(raw_ts, (int, float)):
            continue
        candidates.append((idx, record, float(raw_ts)))
    if not candidates:
        return empty("no_numeric_timestamps")

    best_ts = max(item[2] for item in candidates) if mode == "latest" else min(item[2] for item in candidates)
    best = [(idx, rec, ts) for idx, rec, ts in candidates if ts == best_ts]
    if len(best) > 1:
        return empty("ambiguous_timestamp_tie", best_ts, [rec for _, rec, _ in best], "do not guess before side-effect action")

    selected_index, selected_record, selected_timestamp = best[0]
    selected_id = _select_id(selected_record)
    if not selected_id:
        return selected_only("missing_target_id", selected_index, selected_record, selected_timestamp)

    def has_updates(values):
        for _key, value in values.items():
            if value is None:
                continue
            if isinstance(value, str) and value.strip() == "":
                continue
            return True
        return False

    action = raw_action
    if action in {"modify", "update"}:
        if "reminder_id" in selected_record:
            action = "modify_reminder"
        else:
            action = "modify_contact"
    elif action in {"remove", "delete"}:
        if "reminder_id" in selected_record:
            action = "remove_reminder"
        else:
            action = "remove_contact"

    downstream_tool_name = ""
    downstream_tool_kwargs = {}
    if action in {"modify_contact", "update_contact"}:
        person_id = selected_record.get("person_id") or selected_record.get("sender_person_id") or selected_record.get("recipient_person_id")
        if not person_id:
            return selected_only("missing_person_id", selected_index, selected_record, selected_timestamp, "modify_contact")
        downstream_tool_name = "modify_contact"
        if not has_updates(updates):
            return selected_only("missing_update_fields", selected_index, selected_record, selected_timestamp, downstream_tool_name)
        downstream_tool_kwargs = {"person_id": person_id, **updates}
    elif action in {"remove_contact", "delete_contact"}:
        person_id = selected_record.get("person_id") or selected_record.get("sender_person_id") or selected_record.get("recipient_person_id")
        if not person_id:
            return selected_only("missing_person_id", selected_index, selected_record, selected_timestamp, "remove_contact")
        downstream_tool_name = "remove_contact"
        downstream_tool_kwargs = {"person_id": person_id}
    elif action in {"modify_reminder", "update_reminder"}:
        if "reminder_id" not in selected_record:
            return selected_only("missing_reminder_id", selected_index, selected_record, selected_timestamp, "modify_reminder")
        downstream_tool_name = "modify_reminder"
        if not has_updates(updates):
            return selected_only("missing_update_fields", selected_index, selected_record, selected_timestamp, downstream_tool_name)
        downstream_tool_kwargs = {"reminder_id": selected_record.get("reminder_id"), **updates}
    elif action in {"remove_reminder", "delete_reminder"}:
        if "reminder_id" not in selected_record:
            return selected_only("missing_reminder_id", selected_index, selected_record, selected_timestamp, "remove_reminder")
        downstream_tool_name = "remove_reminder"
        downstream_tool_kwargs = {"reminder_id": selected_record.get("reminder_id")}
    elif action in {"send_message", "send"}:
        content = updates.get("content") or updates.get("message") or updates.get("text")
        recipient = selected_record.get("recipient_person_id") or selected_record.get("person_id") or updates.get("recipient_person_id")
        phone = selected_record.get("phone_number") or selected_record.get("recipient_phone_number") or updates.get("phone_number")
        downstream_tool_name = "send_message"
        if not content or (not recipient and not phone):
            return selected_only("missing_message_content_or_recipient", selected_index, selected_record, selected_timestamp, downstream_tool_name)
        downstream_tool_kwargs = {"content": content}
        if recipient:
            downstream_tool_kwargs["recipient_person_id"] = recipient
        else:
            digits = "".join(ch for ch in str(phone) if ch.isdigit())
            downstream_tool_kwargs["phone_number"] = "+1" + digits if len(digits) == 10 else str(phone)
    else:
        return selected_only("unsupported_action", selected_index, selected_record, selected_timestamp)

    return {
        "selected_record": selected_record,
        "selected_index": int(selected_index),
        "selected_id": selected_id,
        "selected_timestamp": float(selected_timestamp),
        "value": selected_id,
        "downstream_tool_name": downstream_tool_name,
        "downstream_tool_kwargs": downstream_tool_kwargs,
        "should_call_tool": True,
        "tie_candidates": [],
        "abstain_reason": "",
        "safety_notes": "call downstream ToolSandbox side-effect next with downstream_tool_kwargs",
        "final_answer_recommendation": "call:" + downstream_tool_name,
    }
